/* OriginAI Study Guide: draws the interactive parts from js/data.js (the code, generated by tools/build_data.py)
   and js/content.js (the explanations). No libraries, no network: it works from a downloaded copy too. */
(function () {
  "use strict";

  const DATA = window.STUDY_DATA || { code: [], examples: {}, repos: {} };
  const CONTENT = window.STUDY_CONTENT || {};
  const CODE = new Map((DATA.code || []).map((entry) => [entry.id, entry]));
  const EXAMPLES = DATA.examples || {};
  const SVG_NS = "http://www.w3.org/2000/svg";
  const missing = new Set();
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

  // The four detectors, copied from originai-vast/model_server/models.json (see the code map entry "models-json")
  const DETECTORS = {
    "veni-hq": { name: "Veni HQ", threshold: 0.5248124511241848, temperature: 1.9924885052003003, spacing: 0.34, clip: 16, stride: 16 },
    "veni-lq": { name: "Veni LQ", threshold: 0.48931823188817947, temperature: 2.5594629377233202, spacing: 0.34, clip: 16, stride: 16 },
    vidi: { name: "Vidi", threshold: 0.5, temperature: 1.0, spacing: 0.33, clip: 10, stride: 10 },
    vici: { name: "Vici", threshold: 0.8321618813027107, temperature: 1.395588533559042, spacing: 0.345, clip: 16, stride: 16 },
  };
  const DETECTOR_NAMES = { "veni-hq": "Veni HQ", "veni-lq": "Veni LQ", vidi: "Vidi", vici: "Vici" };

  // ------------------------------------------------------------------ small helpers
  function setAttrs(node, attrs) {
    if (!attrs) return;
    for (const [key, value] of Object.entries(attrs)) {
      if (value === null || value === undefined || value === false) continue;
      if (key === "text") node.textContent = value;
      else if (key === "html") node.innerHTML = value;
      else if (key.startsWith("on") && typeof value === "function") node.addEventListener(key.slice(2), value);
      else node.setAttribute(key, value === true ? "" : String(value));
    }
  }
  function addKids(node, kids) {
    for (const kid of kids.flat(Infinity)) {
      if (kid === null || kid === undefined || kid === false) continue;
      node.append(kid instanceof Node ? kid : document.createTextNode(String(kid)));
    }
  }
  function el(tag, attrs, ...kids) {
    const node = document.createElement(tag);
    setAttrs(node, attrs);
    addKids(node, kids);
    return node;
  }
  function svg(tag, attrs, ...kids) {
    const node = document.createElementNS(SVG_NS, tag);
    setAttrs(node, attrs);
    addKids(node, kids);
    return node;
  }
  const esc = (text) =>
    String(text).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const fileName = (path) => path.split("/").pop();
  const lineRange = (entry) => (entry.start === entry.end ? String(entry.start) : `${entry.start}–${entry.end}`);
  const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));
  const sigmoid = (x) => 1 / (1 + Math.exp(-x));

  // Python's round(): halves go to the even neighbour (round(8.5) == 8), unlike Math.round
  function roundHalfEven(x) {
    const floor = Math.floor(x);
    if (x - floor === 0.5) return floor % 2 === 0 ? floor : floor + 1;
    return Math.round(x);
  }

  // ------------------------------------------------------------------ code chips
  function fillChip(button) {
    const id = button.dataset.code;
    const entry = CODE.get(id);
    button.type = "button";
    if (!entry) {
      missing.add(id);
      button.classList.add("is-missing");
      button.textContent = id;
      return;
    }
    button.replaceChildren();
    if (entry.symbol && !/\s/.test(entry.symbol)) button.append(el("span", { class: "chip-sym", text: entry.symbol }));
    button.append(el("span", { class: "chip-loc", text: `${fileName(entry.path)}:${lineRange(entry)}` }));
    button.title = `${entry.title}: ${entry.repo}/${entry.path}, lines ${lineRange(entry)}`;
    button.setAttribute("aria-label", `Show the code: ${entry.title} (${entry.path}, lines ${lineRange(entry)})`);
  }
  function chip(id) {
    const button = el("button", { class: "code-chip", type: "button", "data-code": id });
    fillChip(button);
    return button;
  }
  function chipRow(ids) {
    if (!ids || !ids.length) return null;
    return el("div", { class: "chips" }, ids.map(chip));
  }

  // ------------------------------------------------------------------ syntax highlighting
  // Each language is an ordered list of [class, pattern]; the first pattern that matches at a position wins.
  // "id" tokens are then sorted into keywords, constants, built-ins, defined names and calls.
  const LANGS = {
    python: {
      rules: [
        ["com", /#[^\n]*/],
        ["str", /[rRbBuUfF]{0,2}(?:"""[\s\S]*?"""|'''[\s\S]*?''')/],
        ["str", /[rRbBuUfF]{0,2}(?:"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*')/],
        ["dec", /@[A-Za-z_][\w.]*/],
        ["num", /\b(?:0[xXoObB][\da-fA-F_]+|\d[\d_]*(?:\.[\d_]*)?(?:[eE][+-]?\d+)?)\b/],
        ["id", /[A-Za-z_]\w*/],
      ],
      kw: "and as assert async await break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield match case",
      consts: "True False None",
      bi: "self cls print len range int float str dict list tuple set frozenset bool bytes isinstance issubclass min max sum sorted round open super enumerate zip any all abs getattr setattr hasattr type object map filter iter next reversed repr hash vars Exception ValueError KeyError OSError RuntimeError TypeError IndexError TimeoutError FileNotFoundError NotImplementedError",
      defs: ["def", "class"],
    },
    javascript: {
      rules: [
        ["com", /\/\/[^\n]*|\/\*[\s\S]*?\*\//],
        ["str", /`(?:[^`\\]|\\[\s\S])*`/],
        ["str", /"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'/],
        ["num", /\b(?:0[xX][\da-fA-F_]+|\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?)\b/],
        ["id", /[A-Za-z_$][\w$]*/],
      ],
      kw: "const let var function return if else for while do switch case break continue new try catch finally throw typeof instanceof in of async await class extends import export from default this void delete yield static",
      consts: "true false null undefined NaN Infinity",
      bi: "window document console Math Number String Object Array JSON Promise Date Map Set Error RegExp Boolean Symbol URL URLSearchParams FormData XMLHttpRequest fetch setTimeout clearTimeout setInterval clearInterval requestAnimationFrame localStorage sessionStorage navigator location history process",
      defs: ["function", "class"],
    },
    html: {
      rules: [
        ["com", /<!--[\s\S]*?-->/],
        ["tag", /<\/?[A-Za-z][\w-]*|\/?>/],
        ["str", /(?<==)(?:"[^"]*"|'[^']*')/],
        ["attr", /[A-Za-z_:@][\w:.-]*(?==)/],
      ],
    },
    yaml: {
      rules: [
        ["com", /(?:^|(?<=\s))#[^\n]*/],
        ["key", /(?<=^[ \t]*(?:- )?)[\w.-]+(?=:(?:\s|$))/],
        ["str", /"(?:[^"\\\n]|\\.)*"|'[^'\n]*'/],
        ["num", /\b\d+(?:\.\d+)?\b/],
        ["id", /[A-Za-z_][\w-]*/],
      ],
      consts: "true false null yes no",
    },
    json: {
      rules: [
        ["key", /"(?:[^"\\\n]|\\.)*"(?=\s*:)/],
        ["str", /"(?:[^"\\\n]|\\.)*"/],
        ["num", /-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b/],
        ["id", /[A-Za-z_]\w*/],
      ],
      consts: "true false null",
    },
    docker: {
      rules: [
        ["com", /^[ \t]*#[^\n]*/],
        ["kw", /^[ \t]*(?:FROM|RUN|COPY|ADD|ENV|ARG|WORKDIR|CMD|ENTRYPOINT|EXPOSE|USER|LABEL|HEALTHCHECK|VOLUME|SHELL|STOPSIGNAL|ONBUILD)\b/],
        ["str", /"(?:[^"\\\n]|\\.)*"|'[^'\n]*'/],
        ["bi", /\$\{[^}\n]*\}|\$[A-Za-z_]\w*/],
        ["num", /\b\d+(?:\.\d+)*\b/],
        ["id", /[A-Za-z_][\w-]*/],
      ],
      kw: "AS if then else elif fi for do done in",
    },
    bash: {
      rules: [
        ["com", /(?:^|(?<=\s))#[^\n]*/],
        ["str", /"(?:[^"\\]|\\.)*"|'[^']*'/],
        ["bi", /\$\{[^}\n]*\}|\$[A-Za-z_]\w*|\$[0-9@#?*!$-]/],
        ["num", /\b\d+\b/],
        ["id", /[A-Za-z_][\w-]*/],
      ],
      kw: "if then else elif fi for while until do done case esac function in export set exec return exit local unset trap",
    },
  };
  const grammars = new Map();
  function grammar(lang) {
    if (grammars.has(lang)) return grammars.get(lang);
    const spec = LANGS[lang];
    const words = (text) => new Set((text || "").split(/\s+/).filter(Boolean));
    const g = spec
      ? {
          re: new RegExp(spec.rules.map(([, rule]) => `(${rule.source})`).join("|"), "gm"),
          classes: spec.rules.map(([cls]) => cls),
          kw: words(spec.kw),
          consts: words(spec.consts),
          bi: words(spec.bi),
          defs: new Set(spec.defs || []),
        }
      : null;
    grammars.set(lang, g);
    return g;
  }
  function tokenize(code, lang) {
    const g = grammar(lang);
    if (!g) return [[null, code]];
    const out = [];
    const re = g.re;
    re.lastIndex = 0;
    let last = 0;
    let previous = "";
    let match;
    while ((match = re.exec(code)) !== null) {
      if (match[0] === "") {
        re.lastIndex += 1;
        continue;
      }
      if (match.index > last) {
        const gap = code.slice(last, match.index);
        out.push([null, gap]);
        if (/\S/.test(gap)) previous = "";
      }
      let group = 1;
      while (match[group] === undefined) group += 1;
      let cls = g.classes[group - 1];
      const text = match[0];
      if (cls === "id") {
        if (g.defs.has(previous)) cls = "fn";
        else if (g.kw.has(text)) cls = "kw";
        else if (g.consts.has(text)) cls = "const";
        else if (g.bi.has(text)) cls = "bi";
        else if (code.charAt(re.lastIndex) === "(") cls = "call";
        else cls = null;
        previous = text;
      } else {
        previous = "";
      }
      out.push([cls, text]);
      last = re.lastIndex;
    }
    if (last < code.length) out.push([null, code.slice(last)]);
    return out;
  }
  // Highlighted HTML, one string per line (a token that spans lines, like a docstring, is split per line)
  function highlightLines(code, lang) {
    const lines = [""];
    for (const [cls, text] of tokenize(code, lang)) {
      text.split("\n").forEach((part, index) => {
        if (index > 0) lines.push("");
        if (part) lines[lines.length - 1] += cls ? `<span class="tk-${cls}">${esc(part)}</span>` : esc(part);
      });
    }
    return lines;
  }
  function codeLinesHtml(code, lang, start) {
    const rows = highlightLines(code, lang).map(
      (html, i) => `<div class="code-line"><span class="ln">${start + i}</span><span class="lc">${html || " "}</span></div>`,
    );
    return `<div class="code-lines">${rows.join("")}</div>`;
  }
  const jsonHtml = (value) => highlightLines(JSON.stringify(value, null, 2), "json").join("\n");

  // ------------------------------------------------------------------ copying
  async function copyText(text, button) {
    let ok = false;
    try {
      await navigator.clipboard.writeText(text);
      ok = true;
    } catch (error) {
      const area = el("textarea", { style: "position:fixed;left:-9999px;top:0", "aria-hidden": "true" });
      area.value = text;
      document.body.append(area);
      area.select();
      try {
        ok = document.execCommand("copy");
      } catch (error2) {
        ok = false;
      }
      area.remove();
    }
    if (button) {
      if (!button.dataset.label) button.dataset.label = button.textContent;
      button.textContent = ok ? "Copied" : "Copy failed";
      clearTimeout(button._timer);
      button._timer = setTimeout(() => {
        button.textContent = button.dataset.label;
      }, 1600);
    }
  }
  function snippet(text, lang) {
    const pre = el("pre", { class: "json-view short", tabindex: "0", html: highlightLines(text, lang).join("\n") });
    const copy = el("button", { type: "button", class: "btn ghost", text: "Copy", onclick: () => copyText(text, copy) });
    return el("div", { class: "curl" }, pre, el("div", { class: "chips" }, copy));
  }

  // ------------------------------------------------------------------ the code drawer
  const drawer = $("#drawer");
  const scrim = $("[data-scrim]");
  let drawerOpener = null;
  let drawerEntry = null;

  function openDrawer(id, opener) {
    const entry = CODE.get(id);
    if (!entry || !drawer) return;
    drawerEntry = entry;
    drawerOpener = opener || document.activeElement;
    $("[data-drawer-path]", drawer).textContent = `${entry.repo} / ${entry.path}, lines ${lineRange(entry)}`;
    $("[data-drawer-title]", drawer).textContent = entry.title;
    $("[data-drawer-desc]", drawer).textContent = entry.desc || "";
    // The public edition carries no code from private repositories: only the file, the lines and the description
    const hasCode = typeof entry.code === "string";
    const link = $("[data-drawer-link]", drawer);
    link.hidden = !entry.url;
    if (entry.url) link.href = entry.url;
    link.textContent = `Open lines ${lineRange(entry)} on GitHub`;
    $("[data-drawer-copy]", drawer).hidden = !hasCode;
    const note = $("[data-drawer-private]", drawer);
    note.hidden = !entry.private;
    note.textContent = hasCode
      ? "Private repository: the GitHub link needs collaborator access."
      : "Private repository: its code isn't included in this public edition.";
    const view = $("[data-drawer-code]", drawer);
    view.innerHTML = hasCode
      ? codeLinesHtml(entry.code, entry.lang, entry.start)
      : `<p class="code-missing">The code of <code>${esc(entry.path)}</code>, lines ${lineRange(entry)}, is in the private <code>${esc(entry.repo)}</code> repository, so this public edition shows only where it is and what it does.</p>`;
    view.tabIndex = 0;
    view.setAttribute("aria-label", `Code: ${entry.path}, lines ${lineRange(entry)}`);
    view.scrollTop = 0;
    view.scrollLeft = 0;
    drawer.hidden = false;
    scrim.hidden = false;
    document.body.classList.add("drawer-open");
    $("[data-drawer-close]", drawer).focus();
  }
  function closeDrawer() {
    if (!drawer || drawer.hidden) return;
    drawer.hidden = true;
    scrim.hidden = true;
    document.body.classList.remove("drawer-open");
    if (/^#code\//.test(location.hash)) history.replaceState(null, "", location.pathname + location.search);
    if (drawerOpener && document.contains(drawerOpener)) drawerOpener.focus();
    drawerOpener = null;
  }
  function setUpDrawer() {
    if (!drawer) return;
    $("[data-drawer-close]", drawer).addEventListener("click", closeDrawer);
    scrim.addEventListener("click", closeDrawer);
    const copy = $("[data-drawer-copy]", drawer);
    copy.addEventListener("click", () => drawerEntry && typeof drawerEntry.code === "string" && copyText(drawerEntry.code, copy));
    drawer.addEventListener("keydown", (event) => {
      if (event.key !== "Tab") return;
      const stops = $$("a[href], button:not([disabled]), [tabindex='0']", drawer).filter((node) => node.offsetParent !== null);
      if (!stops.length) return;
      const first = stops[0];
      const last = stops[stops.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    });
    document.addEventListener("click", (event) => {
      const button = event.target.closest("[data-code], [data-open-code]");
      if (!button || button.closest("#drawer")) return;
      const id = button.dataset.code || button.dataset.openCode;
      if (!CODE.has(id)) return;
      event.preventDefault();
      openDrawer(id, button);
    });
    const fromHash = () => {
      const match = /^#code\/([\w-]+)$/.exec(location.hash);
      if (match && CODE.has(match[1])) openDrawer(match[1], null);
    };
    window.addEventListener("hashchange", fromHash);
    fromHash();
  }

  // ------------------------------------------------------------------ diagrams: the architecture
  const ARCH_NODES = {
    browser: { x: 10, y: 180, w: 180, h: 80, title: "Browser", sub: "Scan page, scanner.js" },
    render: { x: 330, y: 180, w: 220, h: 80, title: "Render server", sub: "FastAPI, server.py" },
    platforms: { x: 330, y: 20, w: 220, h: 64, title: "Social platforms", sub: "TikTok, Facebook, X, Reddit" },
    vast: { x: 700, y: 40, w: 250, h: 64, title: "Vast.ai endpoint", sub: "originai-detectors" },
    worker: { x: 700, y: 180, w: 250, h: 80, title: "GPU worker", sub: "RTX 5090, originai-vast" },
    b2: { x: 700, y: 376, w: 250, h: 64, title: "Backblaze B2", sub: "checkpoints, salik-digma" },
    github: { x: 330, y: 376, w: 220, h: 64, title: "GitHub", sub: "both repositories" },
  };
  const ARCH_EDGES = [
    { a: "browser", b: "render", d: "M190 220 H330", both: true, label: ["pages, uploads,", "polls every 3 s"], lx: 260, ly: 198 },
    { a: "render", b: "platforms", d: "M440 180 V84", label: ["yt-dlp: look up", "and download"], lx: 450, ly: 128, anchor: "start" },
    { a: "render", b: "vast", d: "M550 200 L700 92", label: ["which worker", "is ready?"], lx: 598, ly: 116 },
    { a: "render", b: "worker", d: "M550 232 H700", both: true, label: ["POST /analyze", "GET the upload"], lx: 625, ly: 250 },
    { a: "worker", b: "b2", d: "M825 260 V376", label: ["checkpoints,", "SHA-1 checked"], lx: 835, ly: 312, anchor: "start" },
    { a: "github", b: "render", d: "M440 376 V260", label: ["push = deploy", "(about 2 min)"], lx: 450, ly: 312, anchor: "start" },
    { a: "github", b: "worker", d: "M550 396 L712 260", label: ["worker image", "(ghcr.io)"], lx: 640, ly: 352 },
  ];
  const ACTOR_NAMES = {
    browser: "In the browser",
    render: "On the Render server",
    platforms: "At the platform",
    vast: "At Vast.ai",
    worker: "On the GPU worker",
    b2: "At Backblaze B2",
    github: "At GitHub",
  };
  let markerCount = 0;

  function markers(id) {
    const arrow = (cls) => svg("path", { d: "M0 0 L10 5 L0 10 z", class: cls });
    const marker = (mid, cls) =>
      svg("marker", { id: mid, viewBox: "0 0 10 10", refX: 9, refY: 5, markerWidth: 7, markerHeight: 7, orient: "auto-start-reverse" }, arrow(cls));
    return svg("defs", null, marker(id, "arrow"), marker(`${id}-on`, "arrow-active"));
  }
  function boxNode(key, box, { onPick, interactive = true, className = "node" }) {
    const group = svg("g", { class: className, "data-key": key });
    group.append(
      svg("rect", { x: box.x, y: box.y, width: box.w, height: box.h, rx: 12 }),
      svg("text", { x: box.x + box.w / 2, y: box.y + box.h / 2 - 3, "text-anchor": "middle", class: "n-title", text: box.title }),
      svg("text", { x: box.x + box.w / 2, y: box.y + box.h / 2 + 16, "text-anchor": "middle", class: "n-sub", text: box.sub }),
    );
    if (interactive) {
      setAttrs(group, { tabindex: 0, role: "button", "aria-pressed": "false", "aria-label": `${box.title}: ${box.sub}` });
      group.addEventListener("click", () => onPick(key));
      group.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onPick(key);
        }
      });
    } else {
      group.style.cursor = "default";
    }
    return group;
  }
  function edgeLabel(edge) {
    const text = svg("text", { class: "edge-label", x: edge.lx, y: edge.ly, "text-anchor": edge.anchor || "middle" });
    (edge.label || []).forEach((line, i) => text.append(svg("tspan", { x: edge.lx, dy: i ? 13 : 0, text: line })));
    return text;
  }
  function archDiagram({ onPick = () => {}, label, interactive = true }) {
    const id = `arrow-${(markerCount += 1)}`;
    const root = svg("svg", { class: "diagram", viewBox: "0 0 960 450", role: "group", "aria-label": label });
    root.append(markers(id));
    const edges = {};
    for (const edge of ARCH_EDGES) {
      const path = svg("path", { d: edge.d, class: "edge", "marker-end": `url(#${id})`, "marker-start": edge.both ? `url(#${id})` : null });
      const text = edgeLabel(edge);
      root.append(path, text);
      edges[`${edge.a}|${edge.b}`] = { path, text, both: edge.both, id };
    }
    const nodes = {};
    for (const [key, box] of Object.entries(ARCH_NODES)) {
      nodes[key] = boxNode(key, box, { onPick, interactive });
      root.append(nodes[key]);
    }
    return { root, nodes, edges };
  }
  function setActiveNode(diagram, key, dimOthers = false) {
    for (const [k, group] of Object.entries(diagram.nodes)) {
      group.classList.toggle("is-active", k === key);
      group.classList.toggle("is-dim", dimOthers && k !== key);
      if (group.hasAttribute("aria-pressed")) group.setAttribute("aria-pressed", String(k === key));
    }
  }
  const edgeBetween = (diagram, a, b) => diagram.edges[`${a}|${b}`] || diagram.edges[`${b}|${a}`] || null;
  function setActiveEdge(diagram, active) {
    for (const edge of Object.values(diagram.edges)) {
      const on = edge === active;
      edge.path.classList.toggle("is-active", on);
      edge.text.classList.toggle("is-active", on);
      const marker = `url(#${edge.id}${on ? "-on" : ""})`;
      edge.path.setAttribute("marker-end", marker);
      if (edge.both) edge.path.setAttribute("marker-start", marker);
    }
  }

  function widgetArchitecture(host) {
    const info = CONTENT.architecture || {};
    const panel = el("div", { class: "panel", "aria-live": "polite" });
    const diagram = archDiagram({ onPick: pick, label: "Architecture of OriginAI. Choose a part to read about it." });
    function pick(key) {
      const item = info[key];
      if (!item) return;
      setActiveNode(diagram, key);
      setActiveEdge(diagram, null);
      panel.replaceChildren(
        el("span", { class: "actor-tag", text: ACTOR_NAMES[key] || key }),
        el("h3", { text: item.title }),
        el("ul", null, (item.lines || []).map((line) => el("li", { text: line }))),
        chipRow(item.code),
      );
    }
    host.append(
      el(
        "div",
        { class: "widget" },
        el("div", { class: "diagram-wrap" }, diagram.root),
        el("p", { class: "hint", text: "Click a box (or Tab to it and press Enter). Arrows point from the part that makes the call." }),
        panel,
      ),
    );
    pick("render");
  }

  // ------------------------------------------------------------------ the journey of one scan
  function widgetJourney(host) {
    const journeys = CONTENT.journey || {};
    const modes = [
      ["upload", "File upload"],
      ["link", "Social media link"],
    ];
    let mode = "upload";
    let index = 0;
    const diagram = archDiagram({ label: "Where the current step happens", interactive: false });
    const modeButtons = modes.map(([key, text]) =>
      el("button", {
        type: "button",
        "aria-pressed": String(key === mode),
        text,
        onclick: () => {
          mode = key;
          index = 0;
          render();
        },
      }),
    );
    const back = el("button", { type: "button", class: "btn ghost", text: "← Back", onclick: () => go(-1) });
    const next = el("button", { type: "button", class: "btn", text: "Next →", onclick: () => go(1) });
    const count = el("span", { class: "journey-count", "aria-live": "polite" });
    const panel = el("div", { class: "panel", "aria-live": "polite" });
    const dots = el("ol", { class: "journey-steps", "aria-label": "Steps" });
    const steps = () => journeys[mode] || [];
    function go(delta) {
      index = clamp(index + delta, 0, steps().length - 1);
      render();
    }
    function render() {
      const list = steps();
      const step = list[index];
      if (!step) return;
      modeButtons.forEach((button, i) => button.setAttribute("aria-pressed", String(modes[i][0] === mode)));
      count.textContent = `${index + 1} / ${list.length}`;
      back.disabled = index === 0;
      next.disabled = index === list.length - 1;
      setActiveNode(diagram, step.actor, true);
      const before = list[index - 1];
      let edge = null;
      if (before && before.actor !== step.actor) {
        edge = edgeBetween(diagram, before.actor, step.actor) || edgeBetween(diagram, "render", step.actor);
      }
      setActiveEdge(diagram, edge);
      panel.replaceChildren(
        el("span", { class: "actor-tag", text: ACTOR_NAMES[step.actor] || step.actor }),
        el("h3", { text: `${index + 1}. ${step.title}` }),
        el("p", { text: step.text }),
        chipRow(step.code),
      );
      dots.replaceChildren(
        ...list.map((item, i) =>
          el(
            "li",
            null,
            el("button", {
              type: "button",
              class: i < index ? "is-done" : null,
              "aria-current": i === index ? "step" : null,
              "aria-label": `Step ${i + 1}: ${item.title}`,
              title: item.title,
              text: String(i + 1),
              onclick: () => {
                index = i;
                render();
              },
            }),
          ),
        ),
      );
    }
    const widget = el(
      "div",
      { class: "widget" },
      el(
        "div",
        { class: "journey-top" },
        el("div", { class: "seg", role: "group", "aria-label": "Kind of scan" }, modeButtons),
        el("div", { class: "journey-nav" }, back, count, next),
      ),
      el("div", { class: "diagram-wrap" }, diagram.root),
      panel,
      dots,
      el("p", { class: "hint", text: "Tip: with the focus inside this box, the left and right arrow keys move between steps." }),
    );
    widget.addEventListener("keydown", (event) => {
      if (event.target.closest("input, select, textarea")) return;
      if (event.key === "ArrowRight") go(1);
      else if (event.key === "ArrowLeft") go(-1);
    });
    host.append(widget);
    render();
  }

  // ------------------------------------------------------------------ job stages
  const STATES = {
    scan: { x: 10, y: 130, w: 120, h: 56, title: "Scan", sub: "pressed", kind: "start" },
    accept: { x: 170, y: 130, w: 140, h: 56, title: "job created", sub: "202 Accepted", kind: "start" },
    refused: { x: 170, y: 250, w: 140, h: 56, title: "refused", sub: "400, no job", kind: "bad" },
    fetching: { x: 330, y: 24, w: 130, h: 56, title: "fetching", sub: "links only", kind: "run" },
    queued: { x: 480, y: 130, w: 130, h: 56, title: "queued", sub: "place in line", kind: "run" },
    analyzing: { x: 650, y: 130, w: 140, h: 56, title: "analyzing", sub: "on the GPU", kind: "run" },
    completed: { x: 840, y: 130, w: 150, h: 56, title: "completed", sub: "kept for 1 hour", kind: "end" },
    canceled: { x: 480, y: 250, w: 130, h: 56, title: "canceled", sub: "by the visitor", kind: "stop" },
    failed: { x: 840, y: 250, w: 150, h: 56, title: "failed", sub: "reason + error", kind: "bad" },
  };
  const STATE_INFO_KEY = { scan: "scan", accept: "accept", refused: "refused" };
  const TRANSITIONS = [
    { d: "M130 158 H170" },
    { d: "M70 186 V278 H170", label: ["checks fail"], lx: 78, ly: 240, anchor: "start" },
    { d: "M310 158 H480", label: ["uploads"], lx: 350, ly: 150 },
    { d: "M240 130 V52 H330", label: ["links"], lx: 248, ly: 96, anchor: "start" },
    { d: "M460 52 H545 V130" },
    { d: "M610 158 H650" },
    { d: "M790 158 H840" },
    { d: "M545 186 V250", label: ["Cancel"], lx: 553, ly: 224, anchor: "start" },
    { d: "M395 80 V278 H480", label: ["Cancel"], lx: 403, ly: 224, anchor: "start" },
    { d: "M720 186 V278 H840", label: ["no face, timeout"], lx: 728, ly: 240, anchor: "start" },
  ];
  function widgetLifecycle(host) {
    const info = CONTENT.lifecycle || {};
    const id = `arrow-${(markerCount += 1)}`;
    const root = svg("svg", { class: "diagram", viewBox: "0 0 1000 320", role: "group", "aria-label": "Job stages. Choose a stage to read about it." });
    root.append(markers(id));
    for (const t of TRANSITIONS) {
      root.append(svg("path", { d: t.d, class: "edge", "marker-end": `url(#${id})` }));
      if (t.label) root.append(edgeLabel(t));
    }
    const nodes = {};
    for (const [key, box] of Object.entries(STATES)) {
      nodes[key] = boxNode(key, box, { onPick: pick, className: `node state kind-${box.kind}` });
      root.append(nodes[key]);
    }
    const panel = el("div", { class: "panel", "aria-live": "polite" });
    function pick(key) {
      const item = info[STATE_INFO_KEY[key] || key];
      if (!item) return;
      for (const [k, group] of Object.entries(nodes)) {
        group.classList.toggle("is-active", k === key);
        group.setAttribute("aria-pressed", String(k === key));
      }
      panel.replaceChildren(el("h3", { text: item.title }), el("p", { text: item.text }), chipRow(item.code));
    }
    host.append(el("div", { class: "widget" }, el("div", { class: "diagram-wrap" }, root), panel));
    pick("queued");
  }

  // ------------------------------------------------------------------ the API explorer
  function exampleInfo(name) {
    if (!(name in EXAMPLES)) {
      missing.add(`example:${name}`);
      return null;
    }
    const raw = EXAMPLES[name];
    const wrapped = raw && typeof raw === "object" && typeof raw.status === "number" && "body" in raw;
    const body = wrapped ? raw.body : raw;
    const status = wrapped ? raw.status : /started/.test(name) ? 202 : 200;
    let tag = "";
    if (body && typeof body === "object") {
      if (body.code) tag = body.code;
      else if (body.id && typeof body.status === "string") tag = body.status;
    }
    if (!tag) tag = status === 202 ? "Accepted" : "OK";
    return { name, body, status, tag, live: /^(get|live)_/.test(name) };
  }
  const methodBadge = (method) => el("span", { class: `method ${method.toLowerCase()}`, text: method });
  // A path that may wrap only after a slash: /api/analyses/{id}/<wbr>media/<wbr>{name}
  function pathLabel(path) {
    const span = el("span", { class: "api-path" });
    path.split(/(?<=\/)/).forEach((part, i) => {
      if (i) span.append(el("wbr"));
      span.append(part);
    });
    return span;
  }

  function widgetApi(host) {
    const endpoints = CONTENT.api || [];
    const detail = el("div", { class: "api-detail", "aria-live": "polite" });
    const buttons = endpoints.map((ep, i) =>
      el(
        "button",
        { type: "button", "aria-selected": "false", onclick: () => show(i, true) },
        methodBadge(ep.method),
        pathLabel(ep.path),
      ),
    );
    function show(i, clicked = false) {
      const ep = endpoints[i];
      buttons.forEach((button, j) => button.setAttribute("aria-selected", String(i === j)));
      const infos = [ep.example, ...(ep.errors || [])].filter(Boolean).map(exampleInfo).filter(Boolean);
      const parts = [el("h3", null, methodBadge(ep.method), pathLabel(ep.path)), el("p", { text: ep.what })];
      if (ep.curl) parts.push(el("p", { class: "hint", text: "Try it from a terminal:" }), snippet(ep.curl, "bash"));
      if (infos.length) {
        const tabs = el("div", { class: "example-tabs", role: "group", "aria-label": "Example answers" });
        const meta = el("div", { class: "example-meta" });
        const pre = el("pre", { class: "json-view", tabindex: "0", "aria-label": "Example answer" });
        const pick = (k) => {
          const x = infos[k];
          $$("button", tabs).forEach((button, j) => button.setAttribute("aria-pressed", String(j === k)));
          const cls = x.status >= 400 ? " is-error" : x.status === 202 ? " is-accepted" : "";
          meta.replaceChildren(
            el("span", { class: `http-status${cls}`, text: `HTTP ${x.status}` }),
            el("span", { text: x.live ? "Live answer from real-originai.com, October 18, 2026" : "Recorded from the live site, October 9, 2026" }),
          );
          pre.innerHTML = jsonHtml(x.body);
          pre.scrollTop = 0;
        };
        infos.forEach((x, k) => tabs.append(el("button", { type: "button", "aria-pressed": "false", text: `${x.status} ${x.tag}`, onclick: () => pick(k) })));
        parts.push(el("p", { class: "hint", text: "Real answers (choose one):" }), tabs, meta, pre);
        pick(0);
      } else {
        parts.push(el("p", { class: "hint", text: "No example answer here: this address returns a file, or needs a secret key." }));
      }
      parts.push(chipRow(ep.code));
      detail.replaceChildren(...parts.filter(Boolean));
      // One column (phones): the answer is below the list, so bring it into view
      if (clicked && window.matchMedia("(max-width: 980px)").matches) detail.scrollIntoView({ block: "start" });
    }
    host.append(
      el(
        "div",
        { class: "widget" },
        el("div", { class: "api-grid" }, el("ul", { class: "api-list", "aria-label": "Endpoints" }, buttons.map((b) => el("li", null, b))), detail),
      ),
    );
    show(0);
  }

  // ------------------------------------------------------------------ pipeline and deploy steps
  function stepWidget(host, steps, listClass, label) {
    const panel = el("div", { class: "panel", "aria-live": "polite" });
    const buttons = steps.map((step, i) => el("button", { type: "button", "aria-pressed": "false", text: step.title, onclick: () => pick(i) }));
    function pick(i) {
      buttons.forEach((button, j) => button.setAttribute("aria-pressed", String(i === j)));
      const step = steps[i];
      panel.replaceChildren(el("h3", { text: `${i + 1}. ${step.title}` }), el("p", { text: step.text }), chipRow(step.code));
    }
    host.append(el("div", { class: "widget" }, el("ol", { class: listClass, "aria-label": label }, buttons.map((b) => el("li", null, b))), panel));
    pick(0);
  }
  const widgetPipeline = (host) => stepWidget(host, CONTENT.pipeline || [], "pipe", "Pipeline steps");
  const widgetDeploy = (host) => stepWidget(host, CONTENT.deploy || [], "flow", "Deploy steps");

  // ------------------------------------------------------------------ interleaved phases
  const FPS_CHOICES = [
    [24000 / 1001, "23.976 (24000/1001)"],
    [24, "24"],
    [25, "25"],
    [30000 / 1001, "29.97 (30000/1001)"],
    [30, "30"],
    [50, "50"],
    [60000 / 1001, "59.94 (60000/1001)"],
    [60, "60"],
  ];
  const MAX_FRAMES = 7200; // models.json, whole_video.max_frames: longer videos are subsampled evenly

  // The same arithmetic as detector.py _analyze (k) and phase_clips (the clips), for a video with a face in every frame
  function phasePlan(det, fps, duration) {
    const expected = Math.round(duration * fps);
    const subsample = Math.max(1, Math.ceil(expected / MAX_FRAMES));
    const dense = Math.ceil(expected / subsample);
    const fpsEff = fps / subsample;
    const product = det.spacing * fpsEff;
    const k = Math.max(1, roundHalfEven(product));
    const perPhase = [];
    let clips = 0;
    let segments = 0;
    for (let p = 0; p < k; p += 1) {
      const frames = Math.max(0, Math.ceil((dense - p) / k));
      let n = 0;
      if (frames >= det.clip) {
        segments += 1;
        const offset = k > 1 ? roundHalfEven((p * det.stride) / k) : 0;
        const last = frames - det.clip;
        const starts = new Set([0, last]);
        for (let s = offset; s <= last; s += det.stride) starts.add(s);
        n = starts.size;
      }
      perPhase.push({ p, frames, clips: n });
      clips += n;
    }
    return { expected, subsample, dense, fpsEff, product, k, spacing: k / fpsEff, span: ((det.clip - 1) * k) / fpsEff, clips, segments, perPhase };
  }

  function control(labelText, input, output) {
    return el("div", { class: "control" }, el("div", { class: "control-head" }, el("label", { for: input.id, text: labelText }), output), input);
  }
  function stat(value, label) {
    return el("div", { class: "stat" }, el("b", { text: value }), el("span", { text: label }));
  }
  const fmt = (x, digits) => Number(x.toFixed(digits)).toString();

  function widgetPhases(host) {
    const det = el("select", { id: "ph-det" }, Object.entries(DETECTORS).map(([id, d]) => el("option", { value: id, text: `${d.name}: ${d.spacing} s, ${d.clip}-frame clips` })));
    det.value = "vidi";
    const fps = el("select", { id: "ph-fps" }, FPS_CHOICES.map(([value, text], i) => el("option", { value: String(i), text })));
    fps.value = "2";
    const dur = el("input", { id: "ph-dur", type: "range", min: 10, max: 120, step: 0.01, value: 12.36 });
    const durOut = el("output", { for: "ph-dur" });
    const phase = el("input", { id: "ph-phase", type: "range", min: 0, max: 7, step: 1, value: 0 });
    const phaseOut = el("output", { for: "ph-phase" });
    const stats = el("div", { class: "stats" });
    const formula = el("div", { class: "trace" });
    const strip = el("div", { class: "frames", "aria-hidden": "true" });
    const stripNote = el("p", { class: "hint" });
    const table = el("div", { class: "table-wrap" });
    const match = el("div", { class: "match no" });
    const recorded = EXAMPLES.recorded_scan_vidi_done && EXAMPLES.recorded_scan_vidi_done.coverage;
    const SHOWN = 96;

    function update() {
      const d = DETECTORS[det.value];
      const [fpsValue] = FPS_CHOICES[Number(fps.value)];
      const duration = Number(dur.value);
      const plan = phasePlan(d, fpsValue, duration);
      durOut.textContent = `${duration.toFixed(2)} s`;
      phase.max = String(plan.k - 1);
      if (Number(phase.value) > plan.k - 1) phase.value = String(plan.k - 1);
      const p = Number(phase.value);
      phaseOut.textContent = `phase ${p}`;

      stats.replaceChildren(
        stat(String(plan.k), "phases (k)"),
        stat(`${fmt(plan.spacing, 4)} s`, `spacing used (trained ${d.spacing} s)`),
        stat(plan.dense.toLocaleString(), plan.subsample > 1 ? `frames analyzed (every ${plan.subsample}th)` : "frames analyzed"),
        stat(plan.clips.toLocaleString(), `${d.clip}-frame clips scored`),
        stat(`${fmt(plan.span, 2)} s`, "one clip spans"),
      );
      const fpsText = fmt(plan.fpsEff, 4);
      formula.textContent =
        `frames  = ${plan.expected}${plan.subsample > 1 ? ` -> every ${plan.subsample}th frame (above ${MAX_FRAMES}) = ${plan.dense}` : ""}\n` +
        `k       = round(${d.spacing} x ${fpsText}) = round(${fmt(plan.product, 6)}) = ${plan.k}` +
        (plan.product - Math.floor(plan.product) === 0.5 ? "   (a half: Python rounds to the even number)" : "") +
        `\nspacing = k / fps = ${plan.k} / ${fpsText} = ${fmt(plan.spacing, 4)} s`;

      // The frame strip: each frame's colour is its phase; the outlined ones are the first clip of the chosen phase
      const inClip = new Set();
      for (let i = 0; i < d.clip; i += 1) inClip.add(p + i * plan.k);
      strip.replaceChildren(
        ...Array.from({ length: Math.min(SHOWN, plan.dense) }, (_, f) => {
          const ph = f % plan.k;
          return el("span", {
            class: inClip.has(f) ? "in-clip" : null,
            style: `background: hsl(${Math.round((ph * 360) / plan.k)} 62% 46%)`,
            title: `frame ${f}, phase ${ph}`,
            text: String(ph),
          });
        }),
      );
      const clipFrames = Array.from(inClip).sort((a, b) => a - b);
      const shownList = clipFrames.length > 6 ? `${clipFrames.slice(0, 4).join(", ")}, …, ${clipFrames[clipFrames.length - 1]}` : clipFrames.join(", ");
      stripNote.textContent =
        `The first ${Math.min(SHOWN, plan.dense)} frames, numbered by phase. Outlined: the first clip of phase ${p}, frames ${shownList} ` +
        `(${d.clip} frames, ${fmt(plan.span, 2)} s from first to last). Frames past ${SHOWN - 1} are not drawn.`;

      table.replaceChildren(
        el(
          "table",
          null,
          el("thead", null, el("tr", null, el("th", { text: "Phase" }), el("th", { text: "Frames in it" }), el("th", { text: "Clips" }))),
          el(
            "tbody",
            null,
            plan.perPhase.map((row) => el("tr", null, el("td", { text: String(row.p) }), el("td", { text: String(row.frames) }), el("td", { text: String(row.clips) }))),
          ),
        ),
      );

      if (recorded && det.value === "vidi" && plan.dense === recorded.frames_analyzed && Math.abs(fpsValue - recorded.fps) < 1e-9) {
        const same = plan.k === recorded.phases && plan.clips === recorded.clips;
        match.className = same ? "match" : "match no";
        match.textContent =
          `Same video as the recorded Vidi scan (October 9): the GPU reported ${recorded.phases} phases and ${recorded.clips} clips ` +
          `(coverage.phases, coverage.clips). This calculator gets ${plan.k} and ${plan.clips}${same ? ", the same." : "."}`;
        match.hidden = false;
      } else {
        match.hidden = true;
      }
    }
    [det, fps, dur, phase].forEach((input) => input.addEventListener("input", update));
    const preset = el("button", {
      type: "button",
      text: "The recorded Vidi scan: 12.36 s at 25 fps",
      onclick: () => {
        det.value = "vidi";
        fps.value = "2";
        dur.value = "12.36";
        update();
      },
    });
    const preset2 = el("button", {
      type: "button",
      text: "Veni HQ, 2 minutes at 60 fps",
      onclick: () => {
        det.value = "veni-hq";
        fps.value = "7";
        dur.value = "120";
        update();
      },
    });
    host.append(
      el(
        "div",
        { class: "widget" },
        el(
          "div",
          { class: "controls" },
          control("Detector", det, el("span")),
          control("Frame rate", fps, el("span")),
          control("Length", dur, durOut),
          control("Show the first clip of", phase, phaseOut),
        ),
        el("div", { class: "presets" }, preset, preset2),
        el("p", { class: "hint", text: "Assumes a face in every frame and no gaps, like the recorded scan." }),
        stats,
        formula,
        strip,
        stripNote,
        match,
        el("details", null, el("summary", { text: "Frames and clips per phase" }), table),
        chipRow(["phase-clips", "analyze-main"]),
      ),
    );
    update();
  }

  // ------------------------------------------------------------------ how sure
  function surePieces(p, threshold) {
    const fake = p >= threshold;
    const room = fake ? (p - threshold) / Math.max(0.01, 1 - threshold) : (threshold - p) / Math.max(0.01, threshold);
    const strength = clamp(room, 0, 1);
    const sure = Math.round(50 + 50 * strength);
    const strong = strength >= 0.5;
    const title = fake
      ? strong
        ? "Strong signs of a swapped or edited face."
        : "Some signs of a swapped or edited face."
      : strong
        ? "No signs of a swapped or edited face."
        : "Few signs of a swapped or edited face.";
    return { fake, room, strength, sure, strong, title, x: fake ? 50 + 50 * strength : 50 - 50 * strength };
  }
  function widgetHowSure(host) {
    const det = el("select", { id: "hs-det" }, Object.entries(DETECTORS).map(([id, d]) => el("option", { value: id, text: `${d.name}: line ${fmt(d.threshold, 4)}` })));
    det.value = "vidi";
    const score = el("input", { id: "hs-p", type: "range", min: 0, max: 1, step: 0.0001, value: 0.8784 });
    const scoreOut = el("output", { for: "hs-p" });
    const verdict = el("div", { class: "verdict" });
    const subtitle = el("p", { class: "pick" });
    const dot = el("span", { class: "dot" });
    const tick = el("span", { class: "tick" });
    const meter = el("div", { class: "meter", role: "img" }, tick, dot);
    const trace = el("div", { class: "trace" });
    function update() {
      const d = DETECTORS[det.value];
      const p = Number(score.value);
      const r = surePieces(p, d.threshold);
      scoreOut.textContent = `p = ${p.toFixed(4)}`;
      verdict.className = `verdict ${r.fake ? "fake" : "real"}`;
      verdict.replaceChildren(el("b", { text: r.fake ? "Likely Deepfake" : "Likely Real" }), el("span", { class: "pct", text: `${r.sure}% sure` }));
      subtitle.textContent = r.title;
      dot.style.left = `${r.x}%`;
      tick.dataset.label = `${d.name}'s line (${Math.round(d.threshold * 100)}%)`;
      meter.setAttribute("aria-label", `${r.fake ? "Likely Deepfake" : "Likely Real"}, ${r.sure}% sure, on the ${r.fake ? "deepfake" : "real"} side of ${d.name}'s line.`);
      const t = fmt(d.threshold, 4);
      const ln = Math.log(p / (1 - p));
      const logit = d.temperature * ln;
      const show = (x) => (Number.isFinite(x) ? x.toFixed(4) : x > 0 ? "∞" : "−∞");
      trace.textContent =
        `p = ${p.toFixed(4)} ${r.fake ? ">=" : "<"} line ${t}  ->  ${r.fake ? "Likely Deepfake" : "Likely Real"}\n` +
        (r.fake
          ? `room = (p - line) / (1 - line) = (${p.toFixed(4)} - ${t}) / ${fmt(1 - d.threshold, 4)} = ${r.room.toFixed(4)}\n`
          : `room = (line - p) / line = (${t} - ${p.toFixed(4)}) / ${t} = ${r.room.toFixed(4)}\n`) +
        `sure = round(50 + 50 x ${r.strength.toFixed(4)}) = ${r.sure}%   (${r.strong ? "room >= 0.5: strong" : "room < 0.5: not strong"})\n` +
        `video logit = T x ln(p / (1 - p)) = ${fmt(d.temperature, 4)} x ${show(ln)} = ${show(logit)}`;
    }
    [det, score].forEach((input) => input.addEventListener("input", update));
    const presets = [
      ["The recorded Vidi scan (0.8784)", "vidi", 0.8784],
      ["Vici at 0.80: below its high line", "vici", 0.8],
      ["Veni HQ just past its line (0.53)", "veni-hq", 0.53],
      ["Veni LQ at 0.30", "veni-lq", 0.3],
    ].map(([text, id, p]) =>
      el("button", {
        type: "button",
        text,
        onclick: () => {
          det.value = id;
          score.value = String(p);
          update();
        },
      }),
    );
    host.append(
      el(
        "div",
        { class: "widget" },
        el("div", { class: "controls" }, control("Detector", det, el("span")), control("Calibrated score (prob_fake)", score, scoreOut)),
        el("div", { class: "presets" }, presets),
        verdict,
        subtitle,
        meter,
        el("div", { class: "meter-ends" }, el("span", { text: "← Real (score 0)" }), el("span", { text: "Deepfake (score 1) →" })),
        trace,
        el("p", { class: "hint", text: "Same arithmetic as the result card (scanner.js) and the GPU's read-out (detector.py)." }),
        chipRow(["js-how-sure", "readout"]),
      ),
    );
    update();
  }

  // ------------------------------------------------------------------ Auto
  // Copied from backend/video_quality.py (THRESHOLDS, PREFERENCE) and frontend/js/scanner.js (AUTO_WHY)
  const AUTO_T = { dark: 55, shaky: 1.0, grainy: 4.0, blurry: 200, blocky: 0.015, small: 400 };
  const AUTO_PREF = {
    dark: ["vici", "veni-lq", "vidi", "veni-hq"],
    shaky: ["vici", "veni-lq", "vidi", "veni-hq"],
    grainy: ["vici", "veni-lq", "vidi", "veni-hq"],
    blurry: ["veni-lq", "vici", "vidi", "veni-hq"],
    blocky: ["veni-lq", "vici", "vidi", "veni-hq"],
    small: ["veni-lq", "vici", "vidi", "veni-hq"],
    clean: ["vidi", "veni-hq", "vici", "veni-lq"],
    unchecked: ["vidi", "veni-hq", "vici", "veni-lq"],
  };
  const AUTO_WHY = {
    dark: "your video is quite dark",
    shaky: "the camera moves a lot",
    grainy: "your video looks grainy",
    blurry: "your video looks blurry",
    blocky: "your video looks blocky, like a squeezed copy",
    small: "your video is small, so fine detail is lost",
    clean: "your video looks clean and clear",
    unchecked: "it's the usual choice when a video can't be checked first",
  };
  const MEASURES = [
    { key: "brightness", label: "Brightness (middle of the frame, 0 to 255)", min: 0, max: 255, step: 1, value: 120, digits: 0, rule: "dark below 55" },
    { key: "movement", label: "Movement of the edges (pixels of 96)", min: 0, max: 4, step: 0.05, value: 0.4, digits: 2, rule: "shaky above 1.0" },
    { key: "grain", label: "Grain (estimated noise; clean is 0.3 to 2)", min: 0, max: 10, step: 0.1, value: 1.2, digits: 1, rule: "grainy above 4.0" },
    { key: "sharpness", label: "Sharpness (variance of the Laplacian)", min: 0, max: 1200, step: 5, value: 420, digits: 0, rule: "blurry below 200" },
    { key: "short_side", label: "Shorter side (pixels)", min: 360, max: 1080, step: 2, value: 720, digits: 0, rule: "small below 400" },
    { key: "bpp", label: "Bits per pixel per frame", min: 0, max: 0.3, step: 0.001, value: 0.09, digits: 3, rule: "blocky below 0.015" },
  ];
  // video_quality.checks, reason_for and pick, line for line
  function qualityWords(m) {
    const t = AUTO_T;
    const flag = (value, bad, word) => (value !== null && value !== undefined && bad ? word : "ok");
    let quality = "ok";
    if (m.short_side !== null && m.short_side !== undefined && m.short_side < t.small) quality = "small";
    else if (m.bpp !== null && m.bpp !== undefined && m.bpp < t.blocky) quality = "blocky";
    return {
      light: flag(m.brightness, (m.brightness || 0) < t.dark, "dark"),
      movement: flag(m.movement, (m.movement || 0) > t.shaky, "shaky"),
      grain: flag(m.grain, (m.grain || 0) > t.grainy, "grainy"),
      sharpness: flag(m.sharpness, (m.sharpness || 0) < t.blurry, "blurry"),
      quality,
    };
  }
  function firstProblem(found) {
    for (const key of ["light", "movement", "grain", "sharpness", "quality"]) if (found[key] !== "ok") return found[key];
    return "clean";
  }
  function detectorFor(reason, avoid) {
    const order = AUTO_PREF[reason] || AUTO_PREF.unchecked;
    const allowed = order.filter((m) => !avoid.includes(m));
    const usable = allowed.length ? allowed : order;
    const choice = { model: usable[0], reason, order };
    if (usable[0] !== order[0]) choice.instead_of = order[0];
    return choice;
  }
  function widgetAuto(host) {
    const values = {};
    const inputs = MEASURES.map((m) => {
      const input = el("input", { id: `auto-${m.key}`, type: "range", min: m.min, max: m.max, step: m.step, value: m.value });
      const out = el("output", { for: input.id });
      input.addEventListener("input", update);
      return { m, input, out };
    });
    const unmeasured = el("input", { type: "checkbox", id: "auto-unchecked" });
    unmeasured.addEventListener("change", update);
    const avoidBoxes = Object.entries(DETECTOR_NAMES).map(([id, name]) => {
      const box = el("input", { type: "checkbox", value: id, id: `auto-avoid-${id}` });
      box.addEventListener("change", update);
      return el("label", { for: box.id }, box, name);
    });
    const checkList = el("ul", { class: "auto-checks" });
    const pickText = el("p", { class: "pick" });
    const order = el("ol", { class: "order", "aria-label": "Preference order" });
    const quote = el("div", { class: "quote" });
    const LABELS = { light: "Light", movement: "Movement", grain: "Grain", sharpness: "Sharpness", quality: "Quality (small, then blocky)" };

    function update() {
      for (const { m, input, out } of inputs) {
        values[m.key] = Number(input.value);
        out.textContent = Number(input.value).toFixed(m.digits);
      }
      const avoid = $$("input[type=checkbox]:checked", avoidList).map((box) => box.value);
      const found = unmeasured.checked ? null : qualityWords(values);
      const reason = found ? firstProblem(found) : "unchecked";
      const choice = detectorFor(reason, avoid);
      const keys = Object.keys(LABELS);
      const decider = found ? keys.find((k) => found[k] !== "ok") : null;
      checkList.replaceChildren(
        ...keys.map((key) => {
          const word = found ? found[key] : "not measured";
          const first = key === decider;
          return el(
            "li",
            { class: first ? "is-first" : null },
            el("span", { text: LABELS[key] }),
            el("span", { class: `word${word === "ok" ? "" : found ? " bad" : " na"}`, text: first ? `${word} (decides)` : word }),
          );
        }),
      );
      const name = DETECTOR_NAMES[choice.model];
      pickText.replaceChildren("Reason ", el("code", { text: reason }), " → Auto picks ", el("b", { text: name }));
      order.replaceChildren(
        ...choice.order.map((id) =>
          el("li", { class: id === choice.model ? "is-picked" : avoid.includes(id) ? "is-avoided" : null, text: DETECTOR_NAMES[id] }),
        ),
      );
      let sentence = `Checked with ${name} because ${AUTO_WHY[reason]}.`;
      if (choice.instead_of) sentence += ` ${DETECTOR_NAMES[choice.instead_of]} learned from this clip, so it was skipped.`;
      quote.textContent = `On the result card: “${sentence}”`;
    }
    const avoidList = el("div", { class: "avoid" }, avoidBoxes);
    host.append(
      el(
        "div",
        { class: "widget" },
        el(
          "div",
          { class: "widget-row" },
          el(
            "div",
            null,
            el("div", { class: "controls" }, inputs.map(({ m, input, out }) => control(m.label, input, out))),
            el("p", { class: "hint", text: MEASURES.map((m) => m.rule).join(" · ") }),
            el("div", { class: "control" }, el("label", { for: unmeasured.id }, unmeasured, " The video can't be measured")),
            el("p", { class: "hint", text: "Learned from this clip (a sample from the detector's own collection):" }),
            avoidList,
          ),
          el(
            "div",
            { class: "panel", "aria-live": "polite" },
            el("h3", { text: "The checks, in order" }),
            checkList,
            pickText,
            el("p", { class: "hint", text: "Preference order for this reason (crossed out: learned from the clip):" }),
            order,
            quote,
          ),
        ),
        chipRow(["vq-rules", "vq-choose", "js-auto-rules"]),
      ),
    );
    update();
  }

  // ------------------------------------------------------------------ the code map
  const AREAS = [
    ["serve", "Serving the site and the build"],
    ["upload", "Uploads and where they are stored"],
    ["validate", "Video checks (PyAV)"],
    ["links", "Links (yt-dlp)"],
    ["line", "Jobs and the line"],
    ["gpu-call", "Calling the GPU"],
    ["auto", "Auto"],
    ["security", "API, limits and safety"],
    ["frontend", "The Scan page (browser)"],
    ["worker", "GPU worker (originai-vast)"],
    ["tests", "Tests"],
    ["content", "Page text to review"],
  ];
  const areaName = Object.fromEntries(AREAS);
  let mapState = null;

  function markHtml(text, words) {
    if (!words.length) return esc(text);
    const pattern = new RegExp(`(${words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})`, "gi");
    return String(text)
      .split(pattern)
      .map((part, i) => (i % 2 ? `<mark>${esc(part)}</mark>` : esc(part)))
      .join("");
  }
  function widgetCodeMap(host) {
    const search = el("input", { type: "search", id: "map-search", placeholder: "Search: av.open, yt-dlp, OUT_DIR, cancel, threshold…", autocomplete: "off", "aria-label": "Search the code map" });
    const count = el("span", { class: "map-count", "aria-live": "polite" });
    const filters = el("div", { class: "map-filters", role: "group", "aria-label": "Filter by topic" });
    const results = el("div");
    let area = "";
    const present = new Set((DATA.code || []).map((entry) => entry.area));
    const choices = [["", "All"], ...AREAS.filter(([key]) => present.has(key))];
    const filterButtons = choices.map(([key, label]) =>
      el("button", {
        type: "button",
        "aria-pressed": String(key === area),
        text: label,
        onclick: () => {
          area = key;
          filterButtons.forEach((button, i) => button.setAttribute("aria-pressed", String(choices[i][0] === area)));
          render();
        },
      }),
    );
    filters.append(...filterButtons);

    function render() {
      const words = search.value.toLowerCase().split(/\s+/).filter(Boolean);
      const groups = new Map(AREAS.map(([key]) => [key, []]));
      let shown = 0;
      for (const entry of DATA.code || []) {
        if (area && entry.area !== area) continue;
        const fields = [entry.title, entry.desc, entry.path, entry.symbol || "", entry.id, entry.repo].join(" ").toLowerCase();
        const code = typeof entry.code === "string" ? entry.code.toLowerCase() : "";
        let codeHit = null;
        if (words.length) {
          if (!words.every((w) => fields.includes(w) || code.includes(w))) continue;
          const onlyInCode = words.find((w) => !fields.includes(w));
          if (onlyInCode) {
            const lines = entry.code.split("\n");
            const at = lines.findIndex((line) => line.toLowerCase().includes(onlyInCode));
            if (at >= 0) codeHit = { line: entry.start + at, text: lines[at].trim().slice(0, 140) };
          }
        }
        if (!groups.has(entry.area)) groups.set(entry.area, []);
        groups.get(entry.area).push({ entry, codeHit });
        shown += 1;
      }
      const total = (DATA.code || []).length;
      count.textContent = `${shown} of ${total} functions and settings`;
      const blocks = [];
      for (const [key, items] of groups) {
        if (!items.length) continue;
        blocks.push(
          el(
            "div",
            { class: "map-group" },
            el("h3", { text: areaName[key] || key }),
            el(
              "ul",
              { class: "map-list" },
              items.map(({ entry, codeHit }) =>
                el(
                  "li",
                  { class: "map-item" },
                  el(
                    "div",
                    null,
                    el("div", { class: "t", html: markHtml(entry.title, words) }),
                    el("div", { class: "loc", html: markHtml(`${entry.repo}/${entry.path}, lines ${lineRange(entry)}${entry.symbol ? ` · ${entry.symbol}` : ""}`, words) }),
                    el("div", { class: "d", html: markHtml(entry.desc || "", words) }),
                    codeHit ? el("div", { class: "d" }, `In the code, line ${codeHit.line}: `, el("code", { html: markHtml(codeHit.text, words) })) : null,
                  ),
                  el(
                    "div",
                    { class: "acts" },
                    el("button", { type: "button", class: "btn", "data-open-code": entry.id, text: typeof entry.code === "string" ? "View code" : "Details" }),
                    entry.url
                      ? el("a", { class: "btn ghost", href: entry.url, target: "_blank", rel: "noopener", text: "GitHub", title: entry.private ? "Private repository: needs collaborator access" : "Public repository" })
                      : null,
                  ),
                ),
              ),
            ),
          ),
        );
      }
      results.replaceChildren(...(blocks.length ? blocks : [el("div", { class: "map-empty", text: "Nothing matches. Try a shorter word, or choose All." })]));
    }
    search.addEventListener("input", () => {
      const top = $("#code-search");
      if (top && top.value !== search.value) top.value = search.value;
      render();
    });
    mapState = {
      setQuery(text) {
        search.value = text;
        render();
      },
    };
    host.append(el("div", { class: "widget" }, el("div", { class: "map-tools" }, search, count), filters, results));
    render();
  }

  // ------------------------------------------------------------------ page chrome: theme, menu, search, current section
  function setUpChrome() {
    const root = document.documentElement;
    const themeButton = $("[data-theme-toggle]");
    if (themeButton) {
      themeButton.addEventListener("click", () => {
        const dark = root.dataset.theme ? root.dataset.theme === "dark" : window.matchMedia("(prefers-color-scheme: dark)").matches;
        root.dataset.theme = dark ? "light" : "dark";
        try {
          localStorage.setItem("osg-theme", root.dataset.theme);
        } catch (error) {
          /* private window: the choice lasts until the page closes */
        }
      });
    }

    const menu = $("[data-menu]");
    const sidebar = $("#sidebar");
    const setMenu = (open) => {
      document.body.classList.toggle("menu-open", open);
      if (menu) menu.setAttribute("aria-expanded", String(open));
    };
    if (menu) menu.addEventListener("click", (event) => {
      event.stopPropagation();
      setMenu(!document.body.classList.contains("menu-open"));
    });
    if (sidebar) sidebar.addEventListener("click", (event) => {
      if (event.target.closest("a")) setMenu(false);
    });
    document.addEventListener("click", (event) => {
      if (document.body.classList.contains("menu-open") && !event.target.closest("#sidebar")) setMenu(false);
    });
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        if (drawer && !drawer.hidden) closeDrawer();
        else setMenu(false);
      } else if (event.key === "/" && !event.target.closest("input, textarea, select") && (!drawer || drawer.hidden)) {
        event.preventDefault();
        $("#code-search").focus();
      }
    });

    const form = $("[data-search]");
    const top = $("#code-search");
    if (form && top) {
      top.addEventListener("input", () => mapState && mapState.setQuery(top.value));
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        if (mapState) mapState.setQuery(top.value);
        $("#codemap").scrollIntoView({ behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
      });
    }

    const links = new Map($$(".sidebar a[href^='#']").map((a) => [a.getAttribute("href").slice(1), a]));
    if ("IntersectionObserver" in window) {
      const observer = new IntersectionObserver(
        (records) => {
          for (const record of records) {
            if (!record.isIntersecting) continue;
            links.forEach((a, id) => a.classList.toggle("is-current", id === record.target.id));
          }
        },
        { rootMargin: "-40% 0px -55% 0px" },
      );
      $$("main .section[id]").forEach((section) => observer.observe(section));
    }
  }

  // ------------------------------------------------------------------ start
  const WIDGETS = {
    architecture: widgetArchitecture,
    journey: widgetJourney,
    lifecycle: widgetLifecycle,
    api: widgetApi,
    pipeline: widgetPipeline,
    phases: widgetPhases,
    howsure: widgetHowSure,
    auto: widgetAuto,
    deploy: widgetDeploy,
    codemap: widgetCodeMap,
  };
  function start() {
    $$(".code-chip[data-code]").forEach(fillChip);
    for (const host of $$("[data-widget]")) {
      const make = WIDGETS[host.dataset.widget];
      if (!make) continue;
      try {
        make(host);
      } catch (error) {
        console.error(`The ${host.dataset.widget} widget failed`, error);
        host.append(el("p", { class: "note", text: "This part couldn't be drawn. The rest of the guide still works." }));
      }
    }
    setUpChrome();
    setUpDrawer();
    if (missing.size) console.warn("Study guide: unknown code ids or examples:", Array.from(missing));
    document.documentElement.dataset.ready = "true";
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
  else start();
})();
